import os
import requests

def validate_document_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("MINDEE_API_KEY")
    if not api_key:
        raise ValueError("Missing Mindee API key. Set MINDEE_API_KEY or pass config['api_key'].")
    endpoint = config.get("endpoint") or "https://api.mindee.net/v1/products/mindee/invoices/v4/predict"
    required_fields = config.get("required_fields") or ["invoice_number", "date", "supplier_name", "total_amount"]
    timeout = config.get("timeout", 60)

    headers = {"Authorization": f"Token {api_key}"}

    files = {}
    data = {}

    if isinstance(payload, str):
        files["document"] = open(payload, "rb")
        close_file = True
    elif isinstance(payload, dict):
        close_file = False
        if "file_path" in payload:
            files["document"] = open(payload["file_path"], "rb")
            close_file = True
        elif "file_bytes" in payload:
            filename = payload.get("filename", "document")
            files["document"] = (filename, payload["file_bytes"])
        elif "document_url" in payload:
            data["document_url"] = payload["document_url"]
        else:
            raise ValueError("payload dict must contain one of: file_path, file_bytes, document_url")
    else:
        raise TypeError("payload must be a file path string or dict")

    try:
        response = requests.post(endpoint, headers=headers, files=files or None, data=data or None, timeout=timeout)
        response.raise_for_status()
        api_response = response.json()
    finally:
        if 'close_file' in locals() and close_file and "document" in files and hasattr(files["document"], "close"):
            files["document"].close()

    prediction = (
        api_response.get("document", {})
        .get("inference", {})
        .get("prediction", {})
    )

    aliases = {
        "invoice_number": ["invoice_number"],
        "date": ["date"],
        "supplier_name": ["supplier_name", "supplier", "supplier_company_registrations"],
        "total_amount": ["total_amount", "total_incl", "total_net"],
    }

    validated = {}
    all_required_present = True

    for field in required_fields:
        candidate_keys = aliases.get(field, [field])
        value = None
        confidence = None

        for key in candidate_keys:
            if key in prediction and prediction[key] not in (None, "", []):
                raw = prediction[key]
                if isinstance(raw, dict):
                    value = raw.get("value")
                    confidence = raw.get("confidence")
                    if value in (None, "") and "amount" in raw:
                        value = raw.get("amount")
                elif isinstance(raw, list):
                    if raw:
                        first = raw[0]
                        if isinstance(first, dict):
                            value = first.get("value") or first.get("name") or first.get("amount")
                            confidence = first.get("confidence")
                        else:
                            value = first
                            confidence = None
                else:
                    value = raw
                    confidence = None
                if value not in (None, "", []):
                    break

        present = value not in (None, "", [])
        if not present:
            all_required_present = False

        validated[field] = {
            "value": value,
            "confidence": confidence,
            "present": present,
        }

    result = {
        "provider": "mindee",
        "endpoint": endpoint,
        "required_fields_valid": all_required_present,
        "fields": validated,
        "raw_response": api_response,
    }
    return result
